<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\ValueObject\DcrInitialAccessTokenUsesVO;

trait DcrInitialAccessTokenUsesAttributeHolder
{
    protected DcrInitialAccessTokenUsesVO|int|null $uses = null;
    protected bool $usesAssigned = false;

    public function getUsesOrCurrent(DcrInitialAccessTokenUsesVO $uses): DcrInitialAccessTokenUsesVO
    {
        if ($this->usesAssigned) {
            \assert(null !== $this->uses);
            return DcrInitialAccessTokenUsesVO::from($this->uses);
        } else {
            return $uses;
        }
    }
    public function usesTryBuildInitial(ConstraintFailList $error): ?DcrInitialAccessTokenUsesVO
    {
        return  DcrInitialAccessTokenUsesVO::tryFrom($this->usesAssigned ? $this->uses : 0, $error);
    }
    public function uses(DcrInitialAccessTokenUsesVO|int $uses): static
    {
        $this->uses = $uses;
        $this->usesAssigned = true;
        return $this;
    }
    public function getUses(): ?int
    {
        return $this->uses instanceof DcrInitialAccessTokenUsesVO ? $this->uses->value() : $this->uses;
    }
    public function isUsesAssigned(): bool
    {
        return $this->usesAssigned;
    }
    public function writeUsesTo(mixed $att): void
    {
        if ($this->usesAssigned) {
            \assert(null !== $this->uses);
            $att->uses($this->uses);
        }
    }
    public function readUsesFrom(mixed $att): void
    {
        if ($att->isUsesAssigned()) {
            $uses = $att->getUses();
            \assert(null !== $uses);
            $this->uses($uses);
        }
    }
    public function unsetUses(): static
    {
        $this->usesAssigned = false;
        return $this;
    }
    protected function withDefaultUses(): void
    {
        if ($this->uses === null) {
            $this->uses = 0;
        }
    }
    protected function withAssertedUsesRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->usesAssigned = $this->usesAssigned) {
            $value->uses = DcrInitialAccessTokenUsesVO::tryFrom($this->uses, $errorsList);
        }
    }
}
